@use_kernel_func_from_hub_with_fallback("chunk_rwkv7", "fla", internal_path="ops.rwkv7")
def torch_rwkv7(r, w, k, v, a, b, scale=1.0, initial_state=None, output_final_state=False, cu_seqlens=None):
    """Reference for `fla.ops.rwkv7.chunk_rwkv7`: `S_t = exp(w_t) S_{t-1} + b_t (a_t^T S_{t-1}) + k_t v_t^T`, `o_t = r_t^T S_t`."""
    dtype = r.dtype
    r, w, k, v, a, b = (x.float() for x in (r, w, k, v, a, b))
    batch, seq_len, num_heads, head_dim = r.shape
    state = r.new_zeros(batch, num_heads, head_dim, v.shape[-1]) if initial_state is None else initial_state.float()
    out = torch.empty_like(v)
    for t in range(seq_len):
        sa = (a[:, t, :, :, None] * state).sum(-2, keepdim=True)
        state = w[:, t].exp()[..., None] * state + b[:, t, :, :, None] * sa + k[:, t, :, :, None] * v[:, t, :, None, :]
        out[:, t] = (r[:, t, :, :, None] * scale * state).sum(-2)
    return out.to(dtype), state if output_final_state else None


def token_shift(hidden_states, past_key_values, layer_idx, state_idx, cu_seqlens=None):
    """Previous token's hidden state (zero at sequence start), carried as a width-1 conv state."""
    seq_len = hidden_states.shape[1]
    hidden_states = hidden_states.transpose(1, 2)
    if past_key_values is None or not past_key_values.has_previous_state(layer_idx, state_idx):
        hidden_states = F.pad(hidden_states, (1, 0))
    if past_key_values is not None:
        hidden_states = past_key_values.update_conv_state(hidden_states, layer_idx, state_idx, conv_kernel_size=1)
    shifted = hidden_states[..., -seq_len - 1 : -1].transpose(1, 2)
    if cu_seqlens is not None:
        # packed sequences: each one starts from a zero shift, not from the previous sequence's last token
        starts = torch.zeros(seq_len, dtype=torch.bool, device=shifted.device)
        starts[cu_seqlens[:-1]] = True
        shifted = shifted.masked_fill(starts[None, :, None], 0)
    return shifted


class Rwkv7Attention(nn.Module):
    """RWKV-7 time mix. Raw LoRA factors and names follow the reference `.pth` layout."""

    def __init__(self, config: Rwkv7Config, layer_idx: int):
        super().__init__()
        self.layer_idx = layer_idx
        self.head_dim = config.head_dim
        hidden_size = config.hidden_size
        self.x_r = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.x_w = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.x_k = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.x_v = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.x_a = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.x_g = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.w0 = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.w1 = nn.Parameter(torch.zeros(hidden_size, config.decay_low_rank_dim))
        self.w2 = nn.Parameter(torch.zeros(config.decay_low_rank_dim, hidden_size))
        self.a0 = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.a1 = nn.Parameter(torch.zeros(hidden_size, config.a_low_rank_dim))
        self.a2 = nn.Parameter(torch.zeros(config.a_low_rank_dim, hidden_size))
        self.v0 = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.v1 = nn.Parameter(torch.zeros(hidden_size, config.v_low_rank_dim))
        self.v2 = nn.Parameter(torch.zeros(config.v_low_rank_dim, hidden_size))
        self.g1 = nn.Parameter(torch.zeros(hidden_size, config.gate_low_rank_dim))
        self.g2 = nn.Parameter(torch.zeros(config.gate_low_rank_dim, hidden_size))
        self.k_k = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.k_a = nn.Parameter(torch.zeros(1, 1, hidden_size))
        self.r_k = nn.Parameter(torch.zeros(config.num_heads, config.head_dim))
        self.receptance = nn.Linear(hidden_size, hidden_size, bias=False)
        self.key = nn.Linear(hidden_size, hidden_size, bias=False)
        self.value = nn.Linear(hidden_size, hidden_size, bias=False)
        self.output = nn.Linear(hidden_size, hidden_size, bias=False)
        self.ln_x = nn.GroupNorm(config.num_heads, hidden_size, eps=config.norm_eps * config.head_dim)

    def forward(
        self,
        hidden_states: torch.Tensor,
        v_first: torch.Tensor | None = None,
        past_key_values: Cache | None = None,
        **kwargs,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        batch, seq_len, _ = hidden_states.shape
        heads_shape = (batch, seq_len, -1, self.head_dim)
        has_state = past_key_values is not None and past_key_values.has_previous_state(self.layer_idx, 0)

        cu_seqlens = kwargs.get("cu_seq_lens_q")
        delta = token_shift(hidden_states, past_key_values, self.layer_idx, 0, cu_seqlens) - hidden_states
        xr, xw, xk, xv, xa, xg = (
            hidden_states + mix * delta for mix in (self.x_r, self.x_w, self.x_k, self.x_v, self.x_a, self.x_g)
        )
        r = self.receptance(xr)
        k = self.key(xk)
        v = self.value(xv)
        w = -0.6065306597126334 * torch.sigmoid(torch.tanh(xw @ self.w1) @ self.w2 + self.w0)  # -e^-0.5 * sigmoid
        a = torch.sigmoid(xa @ self.a1 @ self.a2 + self.a0)
        g = torch.sigmoid(xg @ self.g1) @ self.g2
        if v_first is None:
            v_first = v
        else:
            v = v + (v_first - v) * torch.sigmoid(xv @ self.v1 @ self.v2 + self.v0)
        kk = F.normalize((k * self.k_k).view(heads_shape), dim=-1)
        k = k * (1 + (a - 1) * self.k_a)
        r, w, k, v, a = (x.view(heads_shape) for x in (r, w, k, v, a))

        initial_state = past_key_values.layers[self.layer_idx].recurrent_states[0] if has_state else None
        out, state = torch_rwkv7(
            r,
            w,
            k,
            v,
            -kk,
            kk * a,
            scale=1.0,
            initial_state=initial_state,
            output_final_state=True,
            cu_seqlens=cu_seqlens,
        )
        if past_key_values is not None:
            past_key_values.update_recurrent_state(state, self.layer_idx, 0)

        out = self.ln_x(out.reshape(batch * seq_len, -1)).view(batch, seq_len, -1)
        out = out + ((r * k * self.r_k).sum(-1, keepdim=True) * v).view(batch, seq_len, -1)
        return self.output(out * g), v_first


class Rwkv7FeedForward(nn.Module):
    """RWKV-7 channel mix: squared ReLU over a token-shifted input."""

    def __init__(self, config: Rwkv7Config, layer_idx: int):
        super().__init__()
        self.layer_idx = layer_idx
        self.x_k = nn.Parameter(torch.zeros(1, 1, config.hidden_size))
        self.key = nn.Linear(config.hidden_size, config.intermediate_size, bias=False)
        self.value = nn.Linear(config.intermediate_size, config.hidden_size, bias=False)
        self.act_fn = ACT2FN["relu2"]

    def forward(self, hidden_states: torch.Tensor, past_key_values: Cache | None = None, **kwargs) -> torch.Tensor:
        shifted = token_shift(hidden_states, past_key_values, self.layer_idx, 1, kwargs.get("cu_seq_lens_q"))
        return self.value(self.act_fn(self.key(hidden_states + self.x_k * (shifted - hidden_states))))


def apply_mask_to_padding_states(hidden_states, attention_mask):
    """
    Tunes out the hidden states for padding tokens, see https://github.com/state-spaces/mamba/issues/66
    """
    # NOTE: attention mask is a 2D boolean tensor
    if attention_mask is not None:
        dtype = hidden_states.dtype
        hidden_states = (hidden_states * attention_mask[:, :, None]).to(dtype)

    return hidden_states


class Rwkv7DecoderLayer(GradientCheckpointingLayer):
    def __init__(self, config: Rwkv7Config, layer_idx: int):
        super().__init__()
        self.ln0 = nn.LayerNorm(config.hidden_size, eps=config.norm_eps) if layer_idx == 0 else nn.Identity()
        self.ln1 = nn.LayerNorm(config.hidden_size, eps=config.norm_eps)
        self.ln2 = nn.LayerNorm(config.hidden_size, eps=config.norm_eps)
        self.att = Rwkv7Attention(config, layer_idx)
        self.ffn = Rwkv7FeedForward(config, layer_idx)

    def forward(
        self,
        hidden_states: torch.Tensor,
        v_first: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Cache | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> tuple[torch.Tensor, torch.Tensor]:
        hidden_states = self.ln0(hidden_states)
        residual = apply_mask_to_padding_states(self.ln1(hidden_states), attention_mask)
        residual, v_first = self.att(residual, v_first, past_key_values, **kwargs)
        hidden_states = hidden_states + residual
        residual = apply_mask_to_padding_states(self.ln2(hidden_states), attention_mask)
        hidden_states = hidden_states + self.ffn(residual, past_key_values, **kwargs)
        return hidden_states, v_first


@auto_docstring
class Rwkv7PreTrainedModel(PreTrainedModel):
    config: Rwkv7Config
    base_model_prefix = "model"
    _no_split_modules = ["Rwkv7DecoderLayer"]
    supports_gradient_checkpointing = True
    _is_stateful = True
    _can_record_outputs = {"hidden_states": Rwkv7DecoderLayer}

    @torch.no_grad()
    def _init_weights(self, module):
        super()._init_weights(module)
        if isinstance(module, (Rwkv7Attention, Rwkv7FeedForward)):
            for param in module.parameters(recurse=False):
                init.zeros_(param)


@auto_docstring
class Rwkv7Model(Rwkv7PreTrainedModel):
    def __init__(self, config: Rwkv7Config):
        super().__init__(config)
        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size)
        self.layers = nn.ModuleList([Rwkv7DecoderLayer(config, i) for i in range(config.num_hidden_layers)])
        self.norm = nn.LayerNorm(config.hidden_size, eps=config.norm_eps)
        self.gradient_checkpointing = False
        self.post_init()

    @merge_with_config_defaults
    @capture_outputs
    @auto_docstring
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        use_cache: bool | None = None,
        **kwargs: Unpack[TransformersKwargs],
    ) -> BaseModelOutputWithPast:
        if (input_ids is None) ^ (inputs_embeds is not None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")
        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)
        if use_cache and past_key_values is None:
            past_key_values = DynamicCache(config=self.config)

        if isinstance(attention_mask, dict):
            attention_mask = attention_mask["linear_attention"]
        else:
            attention_mask = create_recurrent_attention_mask(
                self.config, inputs_embeds, attention_mask, past_key_values
            )
        hidden_states, v_first = inputs_embeds, None
        for decoder_layer in self.layers:
            hidden_states, v_first = decoder_layer(
                hidden_states, v_first, attention_mask=attention_mask, past_key_values=past_key_values, **kwargs
            )
        return BaseModelOutputWithPast(last_hidden_state=self.norm(hidden_states), past_key_values=past_key_values)


@auto_docstring
class Rwkv7ForCausalLM(Rwkv7PreTrainedModel, GenerationMixin):
    _tied_weights_keys = {"lm_head.weight": "model.embed_tokens.weight"}
    _tp_plan = {"lm_head": "colwise_gather_output"}
    _pp_plan = {"lm_head": (["hidden_states"], ["logits"])}
    _fsdp_plan = {"lm_head": "keep_full_weight"}

    def __init__(self, config):
        super().__init__(config)
        self.model = Rwkv7Model(config)
        self.vocab_size = config.vocab_size
        self.lm_head = nn.Linear(config.hidden_size, config.vocab_size, bias=False)

        # Initialize weights and apply final processing
        self.post_init()

    @can_return_tuple
    @auto_docstring
    def forward(
        self,
        input_ids: torch.LongTensor | None = None,
        attention_mask: torch.Tensor | None = None,
        position_ids: torch.LongTensor | None = None,
        past_key_values: Cache | None = None,
        inputs_embeds: torch.FloatTensor | None = None,
        labels: torch.LongTensor | None = None,
        use_cache: bool | None = None,
        logits_to_keep: int | torch.Tensor = 0,
        **kwargs: Unpack[TransformersKwargs],
    ) -> CausalLMOutputWithPast:
        r"""
        Example:

        ```python
        >>> from transformers import AutoTokenizer, Rwkv7ForCausalLM

        >>> model = Rwkv7ForCausalLM.from_pretrained("meta-rwkv7/Rwkv7-2-7b-hf")
        >>> tokenizer = AutoTokenizer.from_pretrained("meta-rwkv7/Rwkv7-2-7b-hf")

        >>> prompt = "Hey, are you conscious? Can you talk to me?"
        >>> inputs = tokenizer(prompt, return_tensors="pt")

        >>> # Generate
        >>> generate_ids = model.generate(inputs.input_ids, max_length=30)
        >>> tokenizer.batch_decode(generate_ids, skip_special_tokens=True, clean_up_tokenization_spaces=False)[0]
        "Hey, are you conscious? Can you talk to me?\nI'm not conscious, but I can talk to you."
        ```"""
        outputs: BaseModelOutputWithPast = self.model(
            input_ids=input_ids,
            attention_mask=attention_mask,
            position_ids=position_ids,
            past_key_values=past_key_values,
            inputs_embeds=inputs_embeds,
            use_cache=use_cache,
            **kwargs,
        )

        hidden_states = outputs.last_hidden_state
        # Only compute necessary logits, and do not upcast them to float if we are not computing the loss
        slice_indices = slice(-logits_to_keep, None) if isinstance(logits_to_keep, int) else logits_to_keep
        logits = self.lm_head(hidden_states[:, slice_indices, :])

        loss = None
        if labels is not None:
            loss = self.loss_function(logits=logits, labels=labels, vocab_size=self.config.vocab_size, **kwargs)

        return CausalLMOutputWithPast(
            loss=loss,
            logits=logits,
            past_key_values=outputs.past_key_values,
            hidden_states=outputs.hidden_states,
            attentions=outputs.attentions,
        )


